const ANALYTICS_ENDPOINT = process.env.ANALYTICS_URL

export async function logPageView(path: string) {
  if (!ANALYTICS_ENDPOINT) {
    return
  }

  try {
    await fetch(ANALYTICS_ENDPOINT, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        event: "page_view",
        path,
        timestamp: Date.now(),
      }),
    })
  } catch {
    // best-effort: silently discard logging failures
  }
}

