import { after } from "next/server"
import { logPageView } from "@/lib/analytics"

export default function Home() {
  after(async () => {
    await logPageView("/")
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>This page view has been logged without blocking the response.</p>
    </main>
  )
}

